// ** Header file for the Query Result-Format or "qrf" utility library for
// ** SQLite.  See the README.md documentation for additional information.
// */
// /* #include "sqlite3.h" */
// /*
// ** Specification used by clients to define the output format they want
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct sqlite3_qrf_spec {
    iVersion: u8,
    // /* Version number of this structure */
    eStyle: u8,
    // /* Formatting style.  "box", "csv", etc... */
    eEsc: u8,
    // /* How to escape control characters in text */
    eText: u8,
    // /* Quoting style for text */
    eTitle: u8,
    // /* Quating style for the text of column names */
    eBlob: u8,
    // /* Quoting style for BLOBs */
    bTitles: u8,
    // /* True to show column names */
    bWordWrap: u8,
    // /* Try to wrap on word boundaries */
    bTextJsonb: u8,
    // /* Render JSONB blobs as JSON text */
    eDfltAlign: u8,
    // /* Default alignment, no covered by aAlignment */
    eTitleAlign: u8,
    // /* Alignment for column headers */
    bSplitColumn: u8,
    // /* Wrap single-column output into many columns */
    bBorder: u8,
    // /* Show outer border in Box and Table styles */
    nWrap: i16,
    // /* Wrap columns wider than this */
    nScreenWidth: i16,
    // /* Maximum overall table width */
    nLineLimit: i16,
    // /* Maximum number of lines for any row */
    nTitleLimit: i16,
    // /* Maximum number of characters in a title */
    nMultiInsert: u32,
    // /* Add rows to one INSERT until size exceeds */
    nCharLimit: i32,
    // /* Maximum number of characters in a cell */
    nWidth: i32,
    // /* Number of entries in aWidth[] */
    nAlign: i32,
    // /* Number of entries in aAlignment[] */
    aWidth: *mut i16,
    // /* Column widths */
    aAlign: *mut u8,
    // /* Column alignments */
    zColumnSep: *mut i8,
    // /* Alternative column separator */
    zRowSep: *mut i8,
    // /* Alternative row separator */
    zTableName: *mut i8,
    // /* Output table name */
    zNull: *mut i8,
    // /* Rendering of NULL */
    xRender: Option<unsafe extern "C-unwind" fn(*mut (), *mut sqlite3_value) -> *mut i8>,
    // /* Render a value */
    xWrite: Option<unsafe extern "C-unwind" fn(*mut (), *const i8, i64) -> i32>,
    // /* Write output */
    pRenderArg: *mut (),
    // /* First argument to the xRender callback */
    pWriteArg: *mut (),
    // /* First argument to the xWrite callback */
    pzOutput: *mut *mut i8,
    // /* Storage location for output string */
    // /* The following are available in iVersion 2 and later */
    // /* Show the number of rows at end of each query */
    bRowCount: u8,
    zIFmt: *mut i8,
    // /* Format string for integers */
    zFpFmt: *mut i8,
}

