// /* A single line in the EQP output */
#[repr(C)]
#[derive(Clone, Copy)]
struct qrfEQPGraphRow {
    iEqpId: i32,
    // /* ID for this row */
    iParentId: i32,
    // /* ID of the parent row */
    pNext: *mut qrfEQPGraphRow,
    // /* Next row in sequence */
    zText: [i8; 1],
}

// /* Text to display for this row */
// /* All EQP output is collected into an instance of the following */
#[repr(C)]
#[derive(Clone, Copy)]
struct qrfEQPGraph {
    pRow: *mut qrfEQPGraphRow,
    // /* Linked list of all rows of the EQP output */
    pLast: *mut qrfEQPGraphRow,
    // /* Last element of the pRow list */
    nWidth: i32,
    // /* Width of the graph */
    zPrefix: [i8; 400],
}

// /* Graph prefix */
// /*
// ** Private state information.  Subject to change from one release to the
// ** next.
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct Qrf {
    pStmt: *mut sqlite3_stmt,
    // /* The statement whose output is to be rendered */
    db: *mut sqlite3,
    // /* The corresponding database connection */
    pJTrans: *mut sqlite3_stmt,
    // /* JSONB to JSON translator statement */
    pzErr: *mut *mut i8,
    // /* Write error message here, if not NULL */
    pOut: *mut sqlite3_str,
    // /* Accumulated output */
    iErr: i32,
    // /* Error code */
    nCol: i32,
    // /* Number of output columns */
    expMode: i32,
    // /* Original sqlite3_stmt_isexplain() plus 1 */
    mxWidth: i32,
    // /* Screen width */
    mxHeight: i32,
    // /* nLineLimit */
    u: __SlateRecord108,
    nRow: i64,
    // /* Number of rows handled so far */
    actualWidth: *mut i32,
    // /* Actual width of each column */
    zFmt: [i8; 24],
    // /* Space to hold the true integer rendering fmt */
    spec: sqlite3_qrf_spec,
}

#[repr(C)]
#[derive(Clone, Copy)]
union __SlateRecord108 {
    sLine: __SlateRecord109,
    pGraph: *mut qrfEQPGraph,
    // /* EQP graph (Eqp, Stats, and StatsEst) */
    sExpln: __SlateRecord110,
    nIns: u32,
    // /* Bytes used for current INSERT stmt */
}

#[repr(C)]
#[derive(Clone, Copy)]
struct __SlateRecord109 {
    // /* Content for QRF_STYLE_Line */
    mxColWth: i32,
    // /* Maximum display width of any column */
    azCol: *mut *mut i8,
    // /* Names of output columns (MODE_Line) */
}

#[repr(C)]
#[derive(Clone, Copy)]
struct __SlateRecord110 {
    // /* Content for QRF_STYLE_Explain */
    nIndent: i32,
    // /* Slots allocated for aiIndent */
    iIndent: i32,
    // /* Current slot */
    aiIndent: *mut i32,
    // /* Indentation for each opcode */
}

// /* Lookup table to estimate the number of columns consumed by a Unicode
// ** character.
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct __SlateRecord111 {
    w: u8,
    // /* Width of the character in columns */
    iFirst: i32,
    // /* {1, 0x00000}, */
    // /* First character in a span having this width */
}

// /* Append text here */
// /* Text to append */
// /* Use only the first nVal bytes of zVal[] */
// /*
// ** GCC does not define the offsetof() macro so we'll have to do it
// ** ourselves.
// */
// /*
// ** Data for columnar layout, collected into a single object so
// ** that it can be more easily passed into subroutines.
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct qrfColData {
    p: *mut Qrf,
    // /* The QRF instance */
    nCol: i32,
    // /* Number of columns in the table */
    bMultiRow: u8,
    // /* One or more cells will span multiple lines */
    nMargin: u8,
    // /* Width of column margins */
    nRow: i64,
    // /* Number of rows */
    nAlloc: i64,
    // /* Number of cells allocated */
    n: i64,
    // /* Number of cells.  nCol*nRow */
    az: *mut *mut i8,
    // /* Content of all cells */
    aiWth: *mut i32,
    // /* Width of each cell */
    abNum: *mut u8,
    // /* True for each numeric cell */
    a: *mut qrfPerCol,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct qrfPerCol {
    // /* Per-column data */
    z: *mut i8,
    // /* Cache of text for current row */
    w: i32,
    // /* Computed width of this column */
    mxW: i32,
    // /* Maximum natural (unwrapped) width */
    e: u8,
    // /* Alignment */
    fx: u8,
    // /* Width is fixed */
    bNum: u8,
    // /* True if is numeric */
}

// /************************* End ext/misc/pcachetrace.c ********************/
// /************************* Begin ext/misc/shathree.c ******************/
// /*
// ** 2017-03-08
// **
// ** The author disclaims copyright to this source code.  In place of
// ** a legal notice, here is a blessing:
// **
// **    May you do good and not evil.
// **    May you find forgiveness for yourself and forgive others.
// **    May you share freely, never taking more than you give.
// **
// ******************************************************************************
// **
// ** This SQLite extension implements functions that compute SHA3 hashes
// ** in the way described by the (U.S.) NIST FIPS 202 SHA-3 Standard.
// ** Three SQL functions are implemented:
// **
// **     sha3(X,SIZE)
// **     sha3_agg(Y,SIZE)
// **     sha3_query(Z,SIZE)
// **
// ** The sha3(X) function computes the SHA3 hash of the input X, or NULL if
// ** X is NULL.  If inputs X is text, the UTF-8 rendering of that text is
// ** used to compute the hash.  If X is a BLOB, then the binary data of the
// ** blob is used to compute the hash.  If X is an integer or real number,
// ** then that number if converted into UTF-8 text and the hash is computed
// ** over the text.
// **
// ** The sha3_agg(Y) function computes the SHA3 hash of all Y inputs.  Since
// ** order is important for the hash, it is recommended that the Y expression
// ** by followed by an ORDER BY clause to guarantee that the inputs occur
// ** in the desired order.
// **
// ** The sha3_query(Y) function evaluates all queries in the SQL statements of Y
// ** and returns a hash of their results.
// **
// ** The SIZE argument is optional.  If omitted, the SHA3-256 hash algorithm
// ** is used.  If SIZE is included it must be one of the integers 224, 256,
// ** 384, or 512, to determine SHA3 hash variant that is computed.
// **
// ** Because the sha3_agg() and sha3_query() functions compute a hash over
// ** multiple values, the values are encode to use include type information.
// **
// ** In sha3_agg(), the sequence of bytes that gets hashed for each input
// ** Y depends on the datatype of Y:
// **
// **    typeof(Y)='null'         A single "N" is hashed.  (One byte)
// **
// **    typeof(Y)='integer'      The data hash is the character "I" followed
// **                             by an 8-byte big-endian binary of the
// **                             64-bit signed integer.  (Nine bytes total.)
// **
// **    typeof(Y)='real'         The character "F" followed by an 8-byte
// **                             big-ending binary of the double.  (Nine
// **                             bytes total.)
// **
// **    typeof(Y)='text'         The hash is over prefix "Tnnn:" followed
// **                             by the UTF8 encoding of the text.  The "nnn"
// **                             in the prefix is the minimum-length decimal
// **                             representation of the octet_length of the text.
// **                             Notice the ":" at the end of the prefix, which
// **                             is needed to separate the prefix from the
// **                             content in cases where the content starts
// **                             with a digit.
// **
// **    typeof(Y)='blob'         The hash is taken over prefix "Bnnn:" followed
// **                             by the binary content of the blob.  The "nnn"
// **                             in the prefix is the minimum-length decimal
// **                             representation of the byte-length of the blob.
// **
// ** According to the rules above, all of the following SELECT statements
// ** should return TRUE:
// **
// **    SELECT sha3(1) = sha3('1');
// **
// **    SELECT sha3('hello') = sha3(x'68656c6c6f');
// **
// **    WITH a(x) AS (VALUES('xyzzy'))
// **      SELECT sha3_agg(x) = sha3('T5:xyzzy')            FROM a;
// **
// **    WITH a(x) AS (VALUES(x'010203'))
// **      SELECT sha3_agg(x) = sha3(x'42333a010203')       FROM a;
// **
// **    WITH a(x) AS (VALUES(0x123456))
// **      SELECT sha3_agg(x) = sha3(x'490000000000123456') FROM a;
// **
// **    WITH a(x) AS (VALUES(100.015625))
// **      SELECT sha3_agg(x) = sha3(x'464059010000000000') FROM a;
// **
// **    WITH a(x) AS (VALUES(NULL))
// **      SELECT sha3_agg(x) = sha3('N') FROM a;
// **
// **
// ** In sha3_query(), individual column values are encoded as with
// ** sha3_agg(), but with the addition that a single "R" character is
// ** inserted at the start of each row.
// **
// ** Note that sha3_agg() hashes rows for which Y is NULL.  Add a FILTER
// ** clause if NULL rows should be excluded:
// **
// **    SELECT sha3_agg(x ORDER BY rowid) FILTER(WHERE x NOT NULL) FROM t1;
// */
// /* #include "sqlite3ext.h" */
// /* typedef sqlite3_uint64 u64; */
// /* SQLITE_AMALGAMATION */
// /******************************************************************************
// ** The Hash Engine
// */
// /*
// ** Macros to determine whether the machine is big or little endian,
// ** and whether or not that determination is run-time or compile-time.
// **
// ** For best performance, an attempt is made to guess at the byte-order
// ** using C-preprocessor macros.  If that is unsuccessful, or if
// ** -DSHA3_BYTEORDER=0 is set, then byte-order is determined
// ** at run-time.
// */
// /*
// ** State structure for a SHA3 hash in progress
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct SHA3Context {
    u: __SlateRecord117,
    nRate: u32,
    // /* Bytes of input accepted per Keccak iteration */
    nLoaded: u32,
    // /* Input bytes loaded into u.x[] so far this cycle */
    ixMask: u32,
    // /* Insert next input into u.x[nLoaded^ixMask]. */
    iSize: u32,
}

#[repr(C)]
#[derive(Clone, Copy)]
union __SlateRecord117 {
    s: [u64; 25],
    // /* Keccak state. 5x5 lines of 64 bits each */
    x: [u8; 1600],
    // /* ... or 1600 bytes */
}

