// /************************* Begin ext/misc/completion.c ******************/
// /*
// ** 2017-07-10
// **
// ** The author disclaims copyright to this source code.  In place of
// ** a legal notice, here is a blessing:
// **
// **    May you do good and not evil.
// **    May you find forgiveness for yourself and forgive others.
// **    May you share freely, never taking more than you give.
// **
// *************************************************************************
// **
// ** This file implements an eponymous virtual table that returns suggested
// ** completions for a partial SQL input.
// **
// ** Suggested usage:
// **
// **     SELECT DISTINCT candidate COLLATE nocase
// **       FROM completion($prefix,$wholeline)
// **      ORDER BY 1;
// **
// ** The two query parameters are optional.  $prefix is the text of the
// ** current word being typed and that is to be completed.  $wholeline is
// ** the complete input line, used for context.
// **
// ** The raw completion() table might return the same candidate multiple
// ** times, for example if the same column name is used to two or more
// ** tables.  And the candidates are returned in an arbitrary order.  Hence,
// ** the DISTINCT and ORDER BY are recommended.
// **
// ** This virtual table operates at the speed of human typing, and so there
// ** is no attempt to make it fast.  Even a slow implementation will be much
// ** faster than any human can type.
// **
// */
// /* #include "sqlite3ext.h" */
// /* completion_vtab is a subclass of sqlite3_vtab which will
// ** serve as the underlying representation of a completion virtual table
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct completion_vtab {
    base: sqlite3_vtab,
    // /* Base class - must be first */
    db: *mut sqlite3,
}

// /* Database connection for this completion vtab */
// /* completion_cursor is a subclass of sqlite3_vtab_cursor which will
// ** serve as the underlying representation of a cursor that scans
// ** over rows of the result
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct completion_cursor {
    base: sqlite3_vtab_cursor,
    // /* Base class - must be first */
    db: *mut sqlite3,
    // /* Database connection for this cursor */
    nPrefix: i32,
    nLine: i32,
    // /* Number of bytes in zPrefix and zLine */
    zPrefix: *mut i8,
    // /* The prefix for the word we want to complete */
    zLine: *mut i8,
    // /* The whole that we want to complete */
    zCurrentRow: *const i8,
    // /* Current output row */
    szRow: i32,
    // /* Length of the zCurrentRow string */
    pStmt: *mut sqlite3_stmt,
    // /* Current statement */
    iRowid: i64,
    // /* The rowid */
    ePhase: i32,
    // /* Current phase */
    j: i32,
}

// /************************* End ext/misc/completion.c ********************/
// /************************* Begin ext/misc/appendvfs.c ******************/
// /*
// ** 2017-10-20
// **
// ** The author disclaims copyright to this source code.  In place of
// ** a legal notice, here is a blessing:
// **
// **    May you do good and not evil.
// **    May you find forgiveness for yourself and forgive others.
// **    May you share freely, never taking more than you give.
// **
// ******************************************************************************
// **
// ** This file implements a VFS shim that allows an SQLite database to be
// ** appended onto the end of some other file, such as an executable.
// **
// ** A special record must appear at the end of the file that identifies the
// ** file as an appended database and provides the offset to the first page
// ** of the exposed content. (Or, it is the length of the content prefix.)
// ** For best performance page 1 should be located at a disk page boundary,
// ** though that is not required.
// **
// ** When opening a database using this VFS, the connection might treat
// ** the file as an ordinary SQLite database, or it might treat it as a
// ** database appended onto some other file.  The decision is made by
// ** applying the following rules in order:
// **
// **  (1)  An empty file is an ordinary database.
// **
// **  (2)  If the file ends with the appendvfs trailer string
// **       "Start-Of-SQLite3-NNNNNNNN" that file is an appended database.
// **
// **  (3)  If the file begins with the standard SQLite prefix string
// **       "SQLite format 3", that file is an ordinary database.
// **
// **  (4)  If none of the above apply and the SQLITE_OPEN_CREATE flag is
// **       set, then a new database is appended to the already existing file.
// **
// **  (5)  Otherwise, SQLITE_CANTOPEN is returned.
// **
// ** To avoid unnecessary complications with the PENDING_BYTE, the size of
// ** the file containing the database is limited to 1GiB. (1073741824 bytes)
// ** This VFS will not read or write past the 1GiB mark.  This restriction
// ** might be lifted in future versions.  For now, if you need a larger
// ** database, then keep it in a separate file.
// **
// ** If the file being opened is a plain database (not an appended one), then
// ** this shim is a pass-through into the default underlying VFS. (rule 3)
// **/
// /* #include "sqlite3ext.h" */
// /* The append mark at the end of the database is:
// **
// **     Start-Of-SQLite3-NNNNNNNN
// **     123456789 123456789 12345
// **
// ** The NNNNNNNN represents a 64-bit big-endian unsigned integer which is
// ** the offset to page 1, and also the length of the prefix content.
// */
// /*
// ** Maximum size of the combined prefix + database + append-mark.  This
// ** must be less than 0x40000000 to avoid locking issues on Windows.
// */
// /*
// ** Try to align the database to an even multiple of APND_ROUNDUP bytes.
// */
// /*
// ** Forward declaration of objects used by this utility
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct ApndFile {
    // /* Access to a lower-level VFS that (might) implement dynamic loading,
    // ** access to randomness, etc.
    // */
    // /* An open appendvfs file
    // **
    // ** An instance of this structure describes the appended database file.
    // ** A separate sqlite3_file object is always appended. The appended
    // ** sqlite3_file object (which can be accessed using ORIGFILE()) describes
    // ** the entire file, including the prefix, the database, and the
    // ** append-mark.
    // **
    // ** The structure of an AppendVFS database is like this:
    // **
    // **   +-------------+---------+----------+-------------+
    // **   | prefix-file | padding | database | append-mark |
    // **   +-------------+---------+----------+-------------+
    // **                           ^          ^
    // **                           |          |
    // **                         iPgOne      iMark
    // **
    // **
    // ** "prefix file" -  file onto which the database has been appended.
    // ** "padding"     -  zero or more bytes inserted so that "database"
    // **                  starts on an APND_ROUNDUP boundary
    // ** "database"    -  The SQLite database file
    // ** "append-mark" -  The 25-byte "Start-Of-SQLite3-NNNNNNNN" that indicates
    // **                  the offset from the start of prefix-file to the start
    // **                  of "database".
    // **
    // ** The size of the database is iMark - iPgOne.
    // **
    // ** The NNNNNNNN in the "Start-Of-SQLite3-NNNNNNNN" suffix is the value
    // ** of iPgOne stored as a big-ending 64-bit integer.
    // **
    // ** iMark will be the size of the underlying file minus 25 (APND_MARKSIZE).
    // ** Or, iMark is -1 to indicate that it has not yet been written.
    // */
    base: sqlite3_file,
    // /* Subclass.  MUST BE FIRST! */
    iPgOne: i64,
    // /* Offset to the start of the database */
    iMark: i64,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct internal_state {}

#[repr(C)]
#[derive(Clone, Copy)]
struct z_stream_s {
    next_in: *mut u8,
    avail_in: u32,
    total_in: u64,
    next_out: *mut u8,
    avail_out: u32,
    total_out: u64,
    msg: *mut i8,
    state: *mut internal_state,
    zalloc: Option<unsafe extern "C-unwind" fn(*mut (), u32, u32) -> *mut ()>,
    zfree: Option<unsafe extern "C-unwind" fn(*mut (), *mut ())>,
    opaque: *mut (),
    data_type: i32,
    adler: u64,
    reserved: u64,
}

// /* 0: Name of file in zip archive */
// /* 1: POSIX mode for file */
// /* 2: Last modification time (secs since 1970)*/
// /* 3: Size of object */
// /* 4: Raw data */
// /* 5: Uncompressed data */
// /* 6: Compression method (integer) */
// /* 7: Name of zip file */
// /* Index of column "file" in the above */
// /* Windows limitation on filename size */
// /*
// ** The buffer should be large enough to contain 3 65536 byte strings - the
// ** filename, the extra field and the file comment.
// */
// /*
// ** Magic numbers used to read and write zip files.
// **
// ** ZIPFILE_NEWENTRY_MADEBY:
// **   Use this value for the "version-made-by" field in new zip file
// **   entries. The upper byte indicates "unix", and the lower byte
// **   indicates that the zip file matches pkzip specification 3.0.
// **   This is what info-zip seems to do.
// **
// ** ZIPFILE_NEWENTRY_REQUIRED:
// **   Value for "version-required-to-extract" field of new entries.
// **   Version 2.0 is required to support folders and deflate compression.
// **
// ** ZIPFILE_NEWENTRY_FLAGS:
// **   Value for "general-purpose-bit-flags" field of new entries. Bit
// **   11 means "utf-8 filename and comment".
// **
// ** ZIPFILE_SIGNATURE_CDS:
// **   First 4 bytes of a valid CDS record.
// **
// ** ZIPFILE_SIGNATURE_LFH:
// **   First 4 bytes of a valid LFH record.
// **
// ** ZIPFILE_SIGNATURE_EOCD
// **   First 4 bytes of a valid EOCD record.
// */
// /*
// ** The sizes of the fixed-size part of each of the three main data
// ** structures in a zip archive.
// */
// /*
// *** 4.3.16  End of central directory record:
// ***
// ***   end of central dir signature    4 bytes  (0x06054b50)
// ***   number of this disk             2 bytes
// ***   number of the disk with the
// ***   start of the central directory  2 bytes
// ***   total number of entries in the
// ***   central directory on this disk  2 bytes
// ***   total number of entries in
// ***   the central directory           2 bytes
// ***   size of the central directory   4 bytes
// ***   offset of start of central
// ***   directory with respect to
// ***   the starting disk number        4 bytes
// ***   .ZIP file comment length        2 bytes
// ***   .ZIP file comment       (variable size)
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileEOCD {
    iDisk: u16,
    iFirstDisk: u16,
    nEntry: u16,
    nEntryTotal: u16,
    nSize: u32,
    iOffset: u32,
}

// /*
// *** 4.3.12  Central directory structure:
// ***
// *** ...
// ***
// ***   central file header signature   4 bytes  (0x02014b50)
// ***   version made by                 2 bytes
// ***   version needed to extract       2 bytes
// ***   general purpose bit flag        2 bytes
// ***   compression method              2 bytes
// ***   last mod file time              2 bytes
// ***   last mod file date              2 bytes
// ***   crc-32                          4 bytes
// ***   compressed size                 4 bytes
// ***   uncompressed size               4 bytes
// ***   file name length                2 bytes
// ***   extra field length              2 bytes
// ***   file comment length             2 bytes
// ***   disk number start               2 bytes
// ***   internal file attributes        2 bytes
// ***   external file attributes        4 bytes
// ***   relative offset of local header 4 bytes
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileCDS {
    iVersionMadeBy: u16,
    iVersionExtract: u16,
    flags: u16,
    iCompression: u16,
    mTime: u16,
    mDate: u16,
    crc32: u32,
    szCompressed: u32,
    szUncompressed: u32,
    nFile: u16,
    nExtra: u16,
    nComment: u16,
    iDiskStart: u16,
    iInternalAttr: u16,
    iExternalAttr: u32,
    iOffset: u32,
    zFile: *mut i8,
}

// /* Filename (sqlite3_malloc()) */
// /*
// *** 4.3.7  Local file header:
// ***
// ***   local file header signature     4 bytes  (0x04034b50)
// ***   version needed to extract       2 bytes
// ***   general purpose bit flag        2 bytes
// ***   compression method              2 bytes
// ***   last mod file time              2 bytes
// ***   last mod file date              2 bytes
// ***   crc-32                          4 bytes
// ***   compressed size                 4 bytes
// ***   uncompressed size               4 bytes
// ***   file name length                2 bytes
// ***   extra field length              2 bytes
// ***
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileLFH {
    iVersionExtract: u16,
    flags: u16,
    iCompression: u16,
    mTime: u16,
    mDate: u16,
    crc32: u32,
    szCompressed: u32,
    szUncompressed: u32,
    nFile: u16,
    nExtra: u16,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileEntry {
    cds: ZipfileCDS,
    // /* Parsed CDS record */
    mUnixTime: u32,
    // /* Modification time, in UNIX format */
    aExtra: *mut u8,
    // /* cds.nExtra+cds.nComment bytes of extra data */
    iDataOff: i64,
    // /* Offset to data in file (if aData==0) */
    aData: *mut u8,
    // /* cds.szCompressed bytes of compressed data */
    pNext: *mut ZipfileEntry,
}

// /* Next element in in-memory CDS */
// /*
// ** Cursor type for zipfile tables.
// */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileCsr {
    base: sqlite3_vtab_cursor,
    // /* Base class - must be first */
    iId: i64,
    // /* Cursor ID */
    bEof: u8,
    // /* True when at EOF */
    bNoop: u8,
    // /* If next xNext() call is no-op */
    // /* Used outside of write transactions */
    // /* Zip file */
    pFile: *mut _IO_FILE,
    iNextOff: i64,
    // /* Offset of next record in central directory */
    eocd: ZipfileEOCD,
    // /* Parse of central directory record */
    pFreeEntry: *mut ZipfileEntry,
    // /* Free this list when cursor is closed or reset */
    pCurrent: *mut ZipfileEntry,
    // /* Current entry */
    pCsrNext: *mut ZipfileCsr,
}

// /* Next cursor on same virtual table */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileTab {
    base: sqlite3_vtab,
    // /* Base class - must be first */
    zFile: *mut i8,
    // /* Zip file this table accesses (may be NULL) */
    db: *mut sqlite3,
    // /* Host database connection */
    aBuffer: *mut u8,
    // /* Temporary buffer used for various tasks */
    pCsrList: *mut ZipfileCsr,
    // /* List of cursors */
    iNextCsrid: i64,
    // /* The following are used by write transactions only */
    // /* Linked list of all files (if pWriteFd!=0) */
    pFirstEntry: *mut ZipfileEntry,
    pLastEntry: *mut ZipfileEntry,
    // /* Last element in pFirstEntry list */
    pWriteFd: *mut _IO_FILE,
    // /* File handle open on zip archive */
    szCurrent: i64,
    // /* Current size of zip archive */
    szOrig: i64,
}

// /* Virtual table handle */
// /* Number of SQL function arguments */
// /* Name of SQL function */
// /* OUT: Result */
// /* OUT: User data for *pxFunc */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileBuffer {
    a: *mut u8,
    // /* Pointer to buffer */
    n: i32,
    // /* Size of buffer in bytes */
    nAlloc: i32,
}

// /* Byte allocated at a[] */
#[repr(C)]
#[derive(Clone, Copy)]
struct ZipfileCtx {
    nEntry: i32,
    body: ZipfileBuffer,
    cds: ZipfileBuffer,
}

